// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/verification-agent-counts", wrapper.GetVerificationAgentCount)
	router.GET(options.BaseURL+"/verification-agents", wrapper.ListVerificationAgents)
	router.POST(options.BaseURL+"/verification-agents", wrapper.CreateVerificationAgent)
	router.POST(options.BaseURL+"/verification-agents/:agentId/rotate-token", wrapper.RotateVerificationAgentToken)
	router.DELETE(options.BaseURL+"/verification-agents/:agentId", wrapper.DeleteVerificationAgent)
	router.GET(options.BaseURL+"/verification-configs/:databaseId", wrapper.GetVerificationConfig)
	router.PUT(options.BaseURL+"/verification-configs/:databaseId", wrapper.UpdateVerificationConfig)
	router.GET(options.BaseURL+"/verifications", wrapper.ListVerifications)
	router.POST(options.BaseURL+"/verifications", wrapper.StartVerification)
	router.POST(options.BaseURL+"/verifications/:verificationId/cancel", wrapper.CancelVerification)
	router.GET(options.BaseURL+"/verifications/:verificationId", wrapper.GetVerification)
}

