// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetVerificationAgentCount Read the number of verification agents
	// (GET /verification-agent-counts)
	GetVerificationAgentCount(ctx context.Context, request GetVerificationAgentCountRequestObject) (GetVerificationAgentCountResponseObject, error)
	// ListVerificationAgents List verification agents
	// (GET /verification-agents)
	ListVerificationAgents(ctx context.Context, request ListVerificationAgentsRequestObject) (ListVerificationAgentsResponseObject, error)
	// CreateVerificationAgent Create a verification agent
	// (POST /verification-agents)
	CreateVerificationAgent(ctx context.Context, request CreateVerificationAgentRequestObject) (CreateVerificationAgentResponseObject, error)
	// DeleteVerificationAgent Delete a verification agent
	// (DELETE /verification-agents/{agentId})
	DeleteVerificationAgent(ctx context.Context, request DeleteVerificationAgentRequestObject) (DeleteVerificationAgentResponseObject, error)
	// RotateVerificationAgentToken Rotate a verification agent token
	// (POST /verification-agents/{agentId}/rotate-token)
	RotateVerificationAgentToken(ctx context.Context, request RotateVerificationAgentTokenRequestObject) (RotateVerificationAgentTokenResponseObject, error)
	// GetVerificationConfig Read the verification config
	// (GET /verification-configs/{databaseId})
	GetVerificationConfig(ctx context.Context, request GetVerificationConfigRequestObject) (GetVerificationConfigResponseObject, error)
	// UpdateVerificationConfig Save the verification config
	// (PUT /verification-configs/{databaseId})
	UpdateVerificationConfig(ctx context.Context, request UpdateVerificationConfigRequestObject) (UpdateVerificationConfigResponseObject, error)
	// ListVerifications List the verifications of a database
	// (GET /verifications)
	ListVerifications(ctx context.Context, request ListVerificationsRequestObject) (ListVerificationsResponseObject, error)
	// StartVerification Start a manual backup verification
	// (POST /verifications)
	StartVerification(ctx context.Context, request StartVerificationRequestObject) (StartVerificationResponseObject, error)
	// GetVerification Read a verification with table counts
	// (GET /verifications/{verificationId})
	GetVerification(ctx context.Context, request GetVerificationRequestObject) (GetVerificationResponseObject, error)
	// CancelVerification Cancel a pending or running verification
	// (POST /verifications/{verificationId}/cancel)
	CancelVerification(ctx context.Context, request CancelVerificationRequestObject) (CancelVerificationResponseObject, error)
}

type StrictHandlerFunc func(ctx *gin.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictGinServerOptions struct {
	// RequestErrorHandlerFunc is called when a request cannot be parsed or
	// decoded. It is invoked for JSON bind failures, form parse/bind errors,
	// multipart reader errors, media type parse errors, missing multipart
	// boundaries, and request body read errors. The default returns 400.
	RequestErrorHandlerFunc func(ctx *gin.Context, err error)
	// HandlerErrorFunc is called when the application handler (or any
	// middleware wrapping it) returns a non-nil error. The default returns 500.
	HandlerErrorFunc func(ctx *gin.Context, err error)
	// ResponseErrorHandlerFunc is called when the response object fails to
	// serialize (Visit*Response returns an error) or when the handler returns
	// an unexpected response type. The default returns 500.
	ResponseErrorHandlerFunc func(ctx *gin.Context, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictGinServerOptions{
		RequestErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		},
		HandlerErrorFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
		ResponseErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictGinServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		}
	}
	if options.HandlerErrorFunc == nil {
		options.HandlerErrorFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictGinServerOptions
}

